package lesson06

// Compact operators copied from lessons 2, 3 and 5, so the planner's plans can actually run and
// we can compare estimated row counts with real ones.

import "sort"

type Operator interface {
	Open()
	Next() (Row, bool)
	Close()
	Schema() []string
}

// Index is a stand-in for lesson 5's B+tree: (key, row id) pairs sorted by key, searched by binary
// search. The planner only needs to know that it exists and what a lookup roughly costs.
type Index struct {
	Col     string
	entries []indexEntry
}

type indexEntry struct {
	key Value
	id  int
}

func BuildIndex(t *Table, col string) *Index {
	ci := indexOf(t.Cols, col)
	idx := &Index{Col: col}
	for id, r := range t.Rows {
		if r[ci] != nil {
			idx.entries = append(idx.entries, indexEntry{r[ci], id})
		}
	}
	sort.SliceStable(idx.entries, func(i, j int) bool { return Compare(idx.entries[i].key, idx.entries[j].key) < 0 })
	return idx
}

// Lookup returns row ids with key op v, in key order (ties in row-id order).
func (x *Index) Lookup(op string, v Value) []int {
	n := len(x.entries)
	first := sort.Search(n, func(i int) bool { return Compare(x.entries[i].key, v) >= 0 }) // first ≥ v
	after := sort.Search(n, func(i int) bool { return Compare(x.entries[i].key, v) > 0 })  // first > v
	lo, hi := 0, n
	switch op {
	case "=":
		lo, hi = first, after
	case "<":
		hi = first
	case "<=":
		hi = after
	case ">":
		lo = after
	case ">=":
		lo = first
	default:
		panic("index can't answer " + op)
	}
	ids := make([]int, 0, hi-lo)
	for _, e := range x.entries[lo:hi] {
		ids = append(ids, e.id)
	}
	return ids
}

func concat(l, r Row) Row { return append(append(make(Row, 0, len(l)+len(r)), l...), r...) }

func and(preds []Expr) Expr {
	e := preds[0]
	for _, p := range preds[1:] {
		e = B("and", e, p)
	}
	return e
}

